// Same normalization the game uses for matching (kept here so the bank can dedupe on its own).
export function normalizeKey(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/\+/g, ' plus ')
    .replace(/#/g, ' sharp ')
    .replace(/[^a-z0-9\s]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/^(the|a|an) /, '')
    .replace(/\s/g, '');
}

const tierForShare = (share) => 1 + RARITY_CUTOFFS.filter((c) => share >= c).length;

// Turn a ranked list into answer objects, dropping duplicate answers and any alias
// that would collide with another answer in the same prompt.
function toAnswers(entries) {
  const claimed = new Set();
  const kept = [];
  entries.forEach((e) => {
    const [text, ...aliases] = e.entry.split('|');
    const key = normalizeKey(text);
    if (!key || claimed.has(key)) return;
    claimed.add(key);
    kept.push({ text, aliasesRaw: aliases, share: e.share });
  });
  return kept.map((k, i) => {
    const aliases = k.aliasesRaw.filter((a) => {
      const n = normalizeKey(a);
      if (!n || claimed.has(n)) return false;
      claimed.add(n);
      return true;
    });
    const share = k.share != null ? k.share : (i + 0.5) / kept.length;
    return { text: k.text, aliases, tier: tierForShare(share), rank: i + 1 };
  });
}

const fullList = (p) => [...p.ranked, ...(EXTRA_ANSWERS[p.id] || [])];

const buildRankedPrompt = (p) => {
  const list = fullList(p);
  const answers = toAnswers(list.map((entry, i) => ({ entry, share: null, i, n: list.length })));
  return { id: p.id, category: p.category, prompt: p.prompt, rankedBy: p.rankedBy, answers };
};

const buildMergedPrompt = (m) => {
  const pool = [];
  m.from.forEach((id) => {
    const src = RANKED_PROMPTS.find((p) => p.id === id);
    if (!src) return;
    const list = fullList(src);
    list.forEach((entry, i) => pool.push({ entry, share: (i + 0.5) / list.length }));
  });
  pool.sort((a, b) => a.share - b.share);
  return { id: m.id, category: m.category, prompt: m.prompt, rankedBy: `relative rank within: ${m.from.join(', ')}`, answers: toAnswers(pool) };
};

export const TRIVIA_BANK = [...CUSTOM_PROMPTS, ...RANKED_PROMPTS.map(buildRankedPrompt), ...MERGED_PROMPTS.map(buildMergedPrompt)];
